import json
import re
from datetime import datetime, timedelta, timezone
from urllib.parse import urljoin

KIND_LABELS = {
    "anime": "番剧",
    "manga": "漫画",
    "music": "音乐",
    "raw": "RAW",
    "stage": "舞台剧",
    "collection": "合集",
    "movie": "剧场版",
    "other": "其他",
}
LANGUAGE_LABELS = {
    "CHS": "简中",
    "CHT": "繁中",
    "JP": "日语",
    "EN": "英语",
    "KO": "韩语",
    "ES": "西班牙语",
    "PT": "葡萄牙语",
    "FR": "法语",
    "DE": "德语",
    "IT": "意大利语",
    "RU": "俄语",
    "AR": "阿拉伯语",
    "HI": "印地语",
    "ID": "印尼语",
    "MS": "马来语",
    "TH": "泰语",
    "VI": "越南语",
    "TL": "菲律宾语/他加禄语",
    "TR": "土耳其语",
    "PL": "波兰语",
    "UK": "乌克兰语",
}
SUBTITLE_LABELS = {
    "EXTERNAL": "外挂字幕",
    "INTERNAL": "内封字幕",
    "EMBEDDED": "内嵌字幕",
    "NONE": "无字幕",
}
NAME_CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_$-"


def skip_ref(text, pos):
    while pos < len(text) and text[pos].isspace():
        pos += 1
    if not text.startswith("$R[", pos):
        return pos
    end = text.find("]", pos)
    if end < 0:
        return pos
    cur = end + 1
    while cur < len(text) and text[cur].isspace():
        cur += 1
    if cur >= len(text) or text[cur] != "=":
        return pos
    cur += 1
    while cur < len(text) and text[cur].isspace():
        cur += 1
    return cur


def value_start(text, key, pos=0):
    marker = key + ":"
    while True:
        idx = text.find(marker, pos)
        if idx < 0:
            return -1
        if idx == 0 or text[idx - 1] not in NAME_CHARS:
            cur = idx + len(marker)
            while cur < len(text) and text[cur].isspace():
                cur += 1
            return skip_ref(text, cur)
        pos = idx + len(marker)


def balanced(text, start):
    pairs = {"{": "}", "[": "]"}
    close = pairs.get(text[start : start + 1])
    if not close:
        return "", start
    depth = 0
    in_string = False
    escaped = False
    for idx in range(start, len(text)):
        ch = text[idx]
        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_string = False
        elif ch == '"':
            in_string = True
        elif ch == text[start]:
            depth += 1
        elif ch == close:
            depth -= 1
            if depth == 0:
                return text[start : idx + 1], idx + 1
    return "", start


def json_string(text, start):
    """Decode a quoted string, including JavaScript hexadecimal escapes.

    Args:
        text: The serialized AniBT data.
        start: The position of the opening double quote.

    Returns:
        The decoded string and the position after its closing quote.
    """
    escaped = False
    for idx in range(start + 1, len(text)):
        ch = text[idx]
        if escaped:
            escaped = False
        elif ch == "\\":
            escaped = True
        elif ch == '"':
            raw = re.sub(
                r"\\(?:x([0-9a-fA-F]{2})|(0)(?!\d)|.)",
                lambda match: (
                    "\\u00" + match[1]
                    if match[1]
                    else "\\u0000"
                    if match[2]
                    else match[0]
                ),
                text[start : idx + 1],
            )
            return json.loads(raw), idx + 1
    return "", start


def field(text, key, default=""):
    start = value_start(text or "", key)
    if start < 0 or start >= len(text):
        return default
    ch = text[start]
    if ch == '"':
        return json_string(text, start)[0]
    if ch in "[{":
        return balanced(text, start)[0]

    end = start
    while end < len(text) and text[end] not in ",}]\n":
        end += 1
    raw = text[start:end].strip()
    if raw in ("", "null", "void 0", "undefined"):
        return default
    try:
        return int(raw)
    except ValueError:
        return raw


def string_list(text, key):
    raw = field(text, key, "[]")
    return [
        json_string(raw, m.start())[0] for m in re.finditer(r'"((?:\\.|[^"\\])*)"', raw)
    ]


def top_objects(array_raw):
    items = []
    pos = 0
    while True:
        start = (array_raw or "").find("{", pos)
        if start < 0:
            return items
        raw, pos = balanced(array_raw, start)
        if not raw:
            return items
        items.append(raw)


def format_size(value):
    """Format a byte count using the site's binary units.

    Args:
        value: The file size in bytes; missing or invalid values are ignored.

    Returns:
        A size with a unit, or an empty string when unavailable.
    """
    try:
        size = int(value)
    except (TypeError, ValueError, OverflowError):
        return ""
    if size < 0:
        return ""
    for unit in ("B", "KB", "MB", "GB", "TB", "PB"):
        if size < 1024 or unit == "PB":
            return f"{size:.1f}".rstrip("0").rstrip(".") + " " + unit
        size /= 1024


def published_at(value):
    """Format an AniBT millisecond timestamp in China Standard Time.

    Args:
        value: The publication time in milliseconds since the Unix epoch.

    Returns:
        A local date and time, or an empty string for an invalid timestamp.
    """
    try:
        local = datetime.fromtimestamp(
            int(value) / 1000, tz=timezone(timedelta(hours=8))
        )
        return local.strftime("%Y-%m-%d %H:%M")
    except (TypeError, ValueError, OverflowError, OSError):
        return ""


def metadata(release):
    """Build the text fields shown in a resource row.

    Args:
        release: The structured AniBT release record.

    Returns:
        Episode, quality, languages, subtitles, format, tags, and revision.
    """
    values = []
    episode = field(release, "episodeKey")
    if episode == "":
        episode = field(release, "episode")
    if episode != "":
        values.append(
            f"第{episode}集"
            if re.fullmatch(r"\d+(?:-\d+)?", str(episode))
            else f"集 {episode}"
        )
    values.append(field(release, "resolution"))
    languages = string_list(release, "language")
    values.extend(LANGUAGE_LABELS.get(code, code) for code in languages)
    subtitle = field(release, "subtitle")
    values.append(SUBTITLE_LABELS.get(subtitle, subtitle))
    values.append(field(release, "format"))
    values.extend(string_list(release, "customTags"))
    version = field(release, "version")
    if version and version != "v1":
        values.append(version)
    return " · ".join(dict.fromkeys(str(value) for value in values if value != ""))


def execute(node_id, node_data, context):
    """Extract text-only search results from the AniBT SSR snapshot.

    Args:
        node_id: The workflow node ID.
        node_data: The workflow node configuration.
        context: The HTTP response and cursor pagination state.

    Raises:
        ValueError: If the request failed or the result snapshot is missing.
    """
    status = context.get("anibt_status", 200)
    if not 200 <= status < 300:
        raise ValueError(f"AniBT request failed with HTTP {status}")
    page_html = (context.get("response") or "").replace("\x00", "\\u0000")
    kind = context.get("anibt_kind") or "anime"
    snapshot_key = "snapshot" if kind == "anime" else "otherSnapshot"
    snap = field(page_html, snapshot_key)
    if not snap:
        raise ValueError("AniBT did not return a result snapshot")

    page_data = field(snap, "page")
    if not isinstance(page_data, str) or not page_data.startswith("["):
        raise ValueError("AniBT did not return a result page")
    items = []
    for item in top_objects(page_data):
        release = field(item, "release")
        title = field(release, "title")
        if not title:
            continue
        release_id = str(field(release, "id") or field(release, "_id"))
        if not release_id:
            continue
        magnet = field(release, "magnetLink")
        torrent_url = field(item, "torrentUrl")
        release_kind = field(release, "category") or kind
        items.append(
            {
                "id": release_id,
                "title": title,
                "link": magnet
                or (urljoin("https://anibt.net", torrent_url) if torrent_url else ""),
                "size": format_size(field(release, "fileSize")),
                "misc": metadata(release),
                "category": KIND_LABELS.get(release_kind, str(release_kind)),
                "uploader": field(item, "groupName") or field(release, "groupId"),
                "uploaded_at": published_at(
                    field(release, "publishedAt") or field(release, "_creationTime")
                ),
            }
        )

    page = context["anibt_current_page"]
    target = context["anibt_target_page"]
    cursor = field(snap, "continueCursor") or None
    if field(snap, "isDone") in {"!0", "true"}:
        cursor = None
    # keep skipped pages out of the requested page's results
    if page != target:
        items = []
    # serialize results so loop context merging does not append earlier pages
    context["search_result"] = json.dumps(
        {
            "total": None,
            "totalPages": page if cursor is None else None,
            "page": target,
            "items": items,
        }
    )
    context["anibt_next_key"] = context["anibt_cache_prefix"] + str(page + 1)
    context["anibt_next_cursor"] = cursor
    context["anibt_current_page"] = page + 1
    context["anibt_cursor"] = cursor
    if cursor is None:
        context["anibt_steps"] = context["anibt_step"] + 1
